// Original vector illustrations for demo products; no invented brand packaging.
export function artKind(p){if(p.art)return p.art;const n=p.name.toLowerCase();const groups=[[/яблок|груш|персик|нектарин|слив|абрикос/,'apple'],[/банан/,'banana'],[/апельсин|мандарин|лимон|лайм|грейпфрут|помело/,'citrus'],[/ягод|клубник|малин|черник|голубик|смородин|вишн|брусник|клюкв/,'berries'],[/виноград/,'grapes'],[/авокадо/,'avocado'],[/томат|помидор/,'tomato'],[/огур|кабач|цукини|баклаж/,'cucumber'],[/морков|редис|св[её]кл/,'carrot'],[/картоф/,'potato'],[/перец слад|перец болгар/,'pepper'],[/гриб|шампиньон|вешенк/,'mushroom'],[/салат|зелень|лук|капуст|брокколи|шпинат|укроп|петруш|кинза|сельдерей/,'greens'],[/молоко|кефир|ряженк|сливки|напиток овсян/,'milk'],[/йогурт|творог|сметан/,'yogurt'],[/сыр|фета|моцарелл|пармезан|рикотт/,'cheese'],[/яйц/,'egg'],[/курин|куриц|индейк|птиц/,'chicken'],[/говядин|свинин|фарш|ветчин|колбас|сосиск/,'meat'],[/лосос|форел|рыб|треск|минта|сельд|тунец|кревет|мидии|кальмар/,'fish'],[/хлеб|лаваш|батон|тост/,'bread'],[/булоч|круассан|пирог|слойк/,'pastry'],[/макарон|паста|спагетти|лапша|вермишел/,'pasta'],[/масло|уксус|вода/,'bottle'],[/сок|нектар|морс|лимонад/,'juice'],[/кофе|какао/,'coffee'],[/чай/,'tea'],[/шоколад/,'chocolate'],[/печень|крекер|вафл/,'cookie'],[/орех|миндал|фундук|арахис|семечк|фисташк|кешью/,'nuts'],[/соус|паста томат|мед|мёд|джем|консерв|оливк|фасоль|нут|кукуруз|горош/,'jar']];return groups.find(([rx])=>rx.test(n))?.[1]||'grain';}
const palette={apple:'#dc503f',banana:'#edc851',citrus:'#f1a63e',berries:'#c43f58',grapes:'#92ae4d',avocado:'#739043',tomato:'#e45943',cucumber:'#6a934c',carrot:'#e69249',potato:'#c9a777',greens:'#6d9d49',pepper:'#d65139',mushroom:'#b49879',milk:'#84b5cd',yogurt:'#86b1a0',cheese:'#e7c061',egg:'#dec4a3',meat:'#c67772',chicken:'#d5a78c',fish:'#e9956c',bread:'#c78b4c',pastry:'#d6a56c',grain:'#c5a064',pasta:'#e0b44d',jar:'#8f9b5e',bottle:'#869e60',juice:'#eca958',tea:'#779766',coffee:'#a87e60',chocolate:'#86604a',cookie:'#c3935d',frozen:'#7caebe',meal:'#9baf7b',nuts:'#b58b59'};
export function productArt(p,id='product'){
 const kind=artKind(p),c=palette[kind]||'#b3996b',gid='g'+id.replace(/[^a-zA-Z0-9]/g,'');let shape='';
 const leaf='<path d="M89 39c1-15 15-17 24-15-4 12-12 17-24 15Z" fill="#6a9543"/>';
 const grains=Array.from({length:21},(_,i)=>`<ellipse cx="${67+(i%5)*11}" cy="${77+Math.floor(i/5)*8}" rx="4" ry="2.5" transform="rotate(${i%3*20} ${67+(i%5)*11} ${77+Math.floor(i/5)*8})" fill="${i%2?'#f2dc98':'#d9bd72'}"/>`).join('');
 if(kind==='apple'||kind==='tomato')shape=`${leaf}<path d="M89 46c-14-19-47-7-47 22 0 30 24 57 45 51 22 8 49-19 49-50 0-29-31-42-47-23Z" fill="url(#${gid})"/><path d="M89 48 85 28" stroke="#715839" stroke-width="5" stroke-linecap="round"/>${kind==='tomato'?'<path d="m88 49-21-9 10 14-17 3 22 4 8 12 4-16 23-7-23-3 9-15Z" fill="#608946"/>':'<path d="M58 62q-8 19 0 34" stroke="#fff" stroke-opacity=".3" stroke-width="7" stroke-linecap="round"/>'}`;
 else if(kind==='banana')shape=`<path d="M44 39c4 46 30 67 80 43-16 48-83 42-92-17-3-15 0-24 12-26Z" fill="#e4b43f"/><path d="M58 32c2 49 29 65 71 34-8 49-76 52-84-7-2-15 1-26 13-27Z" fill="url(#${gid})"/><path d="m57 33 0-10" stroke="#7e7041" stroke-width="5"/>`;
 else if(kind==='citrus')shape=`<circle cx="83" cy="76" r="44" fill="url(#${gid})"/>${leaf}<circle cx="122" cy="94" r="28" fill="#fff4d5"/><circle cx="122" cy="94" r="23" fill="#f2b74d"/>${Array.from({length:8},(_,i)=>`<path d="M122 94v-24" stroke="#fff3ce" stroke-width="2" transform="rotate(${i*45} 122 94)"/>`).join('')}`;
 else if(kind==='avocado')shape='<path d="M82 27c-14 0-18 21-30 40-26 38-12 59 21 59 35 0 52-24 28-63-8-15-4-36-19-36Z" fill="#536d3a"/><path d="M103 31c-14 0-17 20-28 39-19 32-9 55 22 55 31 0 45-24 26-57-11-20-7-37-20-37Z" fill="#c9d882" stroke="#739244" stroke-width="4"/><ellipse cx="100" cy="94" rx="19" ry="21" fill="#976645"/><ellipse cx="95" cy="89" rx="10" ry="11" fill="#af8059"/>';
 else if(kind==='berries'||kind==='grapes')shape=`${Array.from({length:11},(_,i)=>`<circle cx="${54+(i%4)*22+(Math.floor(i/4)%2)*9}" cy="${63+Math.floor(i/4)*19}" r="16" fill="${i%2?c:`url(#${gid})`}"/>`).join('')}${leaf}`;
 else if(kind==='cucumber')shape=`<g transform="rotate(-31 90 75)"><rect x="64" y="20" width="43" height="114" rx="22" fill="url(#${gid})"/><path d="M75 42v70 M95 40v77" stroke="#a1ba75" stroke-width="3" stroke-linecap="round" opacity=".5"/></g><circle cx="123" cy="106" r="22" fill="#bdd591" stroke="#779b54" stroke-width="5"/><ellipse cx="123" cy="106" rx="9" ry="15" fill="#e3eac5"/>`;
 else if(kind==='carrot')shape='<path d="M54 46 118 117c14 14 15 3 9-8L87 36Z" fill="#e78c42"/><path d="m53 43-13-22m20 19 4-25m0 27 16-23" stroke="#6c9b46" stroke-width="8" stroke-linecap="round"/><path d="m78 68 12-9m4 28 10-7m1 24 8-5" stroke="#c76e32" stroke-width="3"/>';
 else if(kind==='potato')shape=`<ellipse cx="67" cy="82" rx="34" ry="29" fill="#bc9868" transform="rotate(-25 67 82)"/><ellipse cx="111" cy="88" rx="34" ry="30" fill="url(#${gid})" transform="rotate(18 111 88)"/><ellipse cx="97" cy="56" rx="30" ry="24" fill="#d5b78e"/><g fill="#987346">${[ [58,80],[78,95],[116,77],[108,100],[89,52],[103,61]].map(([x,y])=>`<circle cx="${x}" cy="${y}" r="2"/>`).join('')}</g>`;
 else if(kind==='greens')shape=`<g fill="url(#${gid})">${[[61,66,30],[96,55,30],[122,75,29],[84,91,37]].map(([x,y,r])=>`<circle cx="${x}" cy="${y}" r="${r}"/>`).join('')}</g><path d="M90 124 82 53m7 52 24-38m-26 29L57 72" stroke="#b9d590" stroke-width="5" stroke-linecap="round"/>`;
 else if(kind==='pepper')shape=`<path d="M90 46c-33-18-54 10-40 47 5 15 17 35 32 23 19 18 38-2 46-24 14-34-6-62-38-46Z" fill="url(#${gid})"/><path d="M88 49c-7-14 4-18 7-23" stroke="#6e8b42" stroke-width="8" stroke-linecap="round"/><path d="M76 61q-12 27 2 44" stroke="#ffffff" stroke-opacity=".2" stroke-width="5" stroke-linecap="round"/>`;
 else if(kind==='mushroom')shape='<path d="M63 81h24l7 43H57Z" fill="#e9dcc3"/><path d="M29 81c0-57 83-63 90 0Z" fill="#b69975"/><path d="M110 91h16l7 34h-28Z" fill="#e9dcc3"/><path d="M88 92c0-39 61-45 67 0Z" fill="#cbb595"/>';
 else if(kind==='milk'||kind==='juice')shape=`<path d="M57 41 71 22h44l15 19v87H57Z" fill="#fdfdf9" stroke="#dddcd3"/><path d="M57 42h73v64H57Z" fill="url(#${gid})"/><path d="m57 41 14-19h44l15 19Z" fill="${c}"/><path d="M71 22v19h44V22" fill="#fff" opacity=".65"/><rect x="66" y="56" width="55" height="38" rx="5" fill="white" opacity=".92"/><text x="93" y="73" text-anchor="middle" font-size="9" fill="#456054" font-family="sans-serif" font-weight="700">${kind==='milk'?'МОЛОКО':'СОК'}</text><path d="M79 83h28" stroke="${c}" stroke-width="3" stroke-linecap="round"/>`;
 else if(kind==='yogurt')shape=`<path d="m52 48 11 77h61l11-77Z" fill="#f9faf5" stroke="#d7dbce"/><path d="m57 72 5 37h63l5-37Z" fill="url(#${gid})"/><ellipse cx="93" cy="48" rx="43" ry="9" fill="#d4e0d7"/><ellipse cx="93" cy="46" rx="39" ry="6" fill="#f7f9f4"/><text x="94" y="96" text-anchor="middle" font-size="9" fill="white" font-family="sans-serif" font-weight="700">НАТУРАЛЬНЫЙ</text>`;
 else if(kind==='cheese')shape='<path d="m34 80 66-41 48 26-1 49-80 9-33-19Z" fill="#ebc666"/><path d="m34 80 66-41 48 26-80 25Z" fill="#f7dc8b"/><path d="m68 90 79-25v49l-80 9Z" fill="#e7b755"/><g fill="#cda243"><ellipse cx="88" cy="105" rx="7" ry="6"/><ellipse cx="127" cy="85" rx="7" ry="6"/><ellipse cx="122" cy="108" rx="4" ry="4"/></g>';
 else if(kind==='egg')shape='<path d="m31 81 25-17h90l10 41-24 20H45Z" fill="#ccbea3"/><g fill="#f4e7d3" stroke="#d5c4a8"><ellipse cx="58" cy="70" rx="17" ry="23"/><ellipse cx="89" cy="65" rx="17" ry="23"/><ellipse cx="121" cy="68" rx="17" ry="23"/></g><path d="m31 81 28 17h90l-17 27H45Z" fill="#b6a688"/>';
 else if(kind==='meat'||kind==='chicken'||kind==='fish')shape=`<rect x="28" y="37" width="129" height="83" rx="17" fill="#ebeee7" stroke="#d4d8ce"/><rect x="35" y="44" width="115" height="67" rx="12" fill="#f8f8f3"/>${kind==='fish'?'<path d="m49 80 60-26 30 37-61 12Z" fill="#ea9b76"/><path d="m61 75 24 24m-9-31 27 26m-14-32 27 29m-14-35 25 29" stroke="#f7cfb7" stroke-width="3"/>':`<path d="M45 84c-7-31 18-45 41-27 15-27 59-11 45 21-6 17-56 37-74 26Z" fill="${c}"/><path d="m63 66 13 25m19-34 11 30" stroke="#f6d6c4" stroke-width="5" stroke-linecap="round"/>`}<rect x="91" y="100" width="48" height="13" rx="2" fill="white"/><path d="M98 105h20 M98 109h32" stroke="#8c9488" stroke-width="1.5"/>`;
 else if(kind==='bread'||kind==='pastry')shape=`<path d="M34 96C25 45 57 34 91 35c35 0 64 21 56 61l-8 21H44Z" fill="url(#${gid})"/><path d="m61 47-7 40m36-46-3 45m32-40 6 43" stroke="#edd0a3" stroke-width="10" stroke-linecap="round"/><path d="M47 107h90" stroke="#8e6234" stroke-width="3" opacity=".35"/>`;
 else if(kind==='bottle')shape=`<rect x="74" y="22" width="32" height="16" rx="4" fill="#668146"/><path d="M77 38v15c0 7-18 12-18 23v48h63V76c0-11-19-16-19-23V38Z" fill="url(#${gid})" opacity=".8"/><rect x="60" y="80" width="61" height="31" rx="4" fill="#f9f4df"/><path d="M91 102c-1-12 7-14 13-13-3 9-7 12-13 13Z" fill="#8b9a57"/><path d="M70 55v64" stroke="#fff" opacity=".25" stroke-width="4"/>`;
 else if(kind==='jar')shape=`<rect x="54" y="28" width="75" height="15" rx="5" fill="#5c7545"/><rect x="57" y="42" width="69" height="82" rx="12" fill="url(#${gid})"/><rect x="59" y="61" width="65" height="40" rx="3" fill="#f7f0dc"/><path d="M81 73h26m-32 7h34m-27 7h25" stroke="#7a815d" stroke-width="3" stroke-linecap="round"/>`;
 else if(kind==='chocolate')shape=`<rect x="42" y="29" width="96" height="96" rx="7" fill="#86634e"/><g fill="#9b7459" stroke="#72503e" stroke-width="2">${Array.from({length:9},(_,i)=>`<rect x="${48+i%3*28}" y="${34+Math.floor(i/3)*29}" width="25" height="26" rx="2"/>`).join('')}</g><path d="M42 82 79 94l59-13v44H42Z" fill="#e3d5b4"/><text x="89" y="113" text-anchor="middle" font-size="9" fill="#795c45" font-family="sans-serif">ШОКОЛАД</text>`;
 else if(kind==='cookie'||kind==='nuts')shape=`${[[62,65],[110,60],[89,99]].map(([x,y])=>`<circle cx="${x}" cy="${y}" r="27" fill="url(#${gid})" stroke="#b58b58" stroke-width="2"/>${[[x-8,y-7],[x+12,y-5],[x-5,y+13]].map(([xx,yy])=>`<circle cx="${xx}" cy="${yy}" r="3" fill="#8e6544"/>`).join('')}`).join('')}`;
 else if(kind==='meal')shape='<ellipse cx="92" cy="87" rx="65" ry="40" fill="#e7e9e1"/><ellipse cx="92" cy="83" rx="58" ry="33" fill="#fafbf8"/><g fill="#92a75f"><circle cx="62" cy="76" r="15"/><circle cx="77" cy="66" r="13"/><circle cx="119" cy="90" r="14"/></g><path d="m77 91 31-29 17 22-27 23Z" fill="#d0a06b"/><g fill="#d35f43"><circle cx="57" cy="96" r="9"/><circle cx="127" cy="70" r="8"/></g>';
 else {const label={grain:'КРУПА',pasta:'ПАСТА',tea:'ЧАЙ',coffee:'КОФЕ',frozen:'ЗАМОРОЗКА'}[kind]||'ПРОДУКТЫ';shape=`<path d="M51 25h78l7 103H44Z" fill="url(#${gid})"/><path d="M51 25h78v9H51Z" fill="#fff" opacity=".45"/><rect x="57" y="47" width="67" height="34" rx="4" fill="#fbf8ee"/><text x="90" y="68" text-anchor="middle" font-size="10" fill="#5b5947" font-family="sans-serif" font-weight="700">${label}</text>${['grain','pasta'].includes(kind)?grains:'<path d="M70 101h40m-35 7h30" stroke="#fff" stroke-opacity=".5" stroke-width="4" stroke-linecap="round"/>'}`;}
 return `<svg class="product-art" viewBox="0 0 180 150" role="img" aria-label="Условная иллюстрация товара"><defs><linearGradient id="${gid}" x1="0" x2="1" y1="0" y2="1"><stop stop-color="${c}"/><stop offset="1" stop-color="${c}" stop-opacity=".72"/></linearGradient></defs><ellipse cx="91" cy="128" rx="54" ry="7" fill="#5e6039" opacity=".09"/>${shape}</svg>`;
}
